class FoodRatings {
    Map<String,String> cuisines=new HashMap<>();
    Map<String,Integer> ratings=new HashMap<>();
    Map<String,TreeSet<String>> ranked=new HashMap<>();
    Comparator<String> order=(a,b)->{
        int compare=Integer.compare(ratings.get(b),ratings.get(a));
        return compare!=0?compare:a.compareTo(b);
    };
    public FoodRatings(String[] foods,String[] cuisines,int[] ratings){
        for(int i=0;i<foods.length;i++){
            this.cuisines.put(foods[i],cuisines[i]);
            this.ratings.put(foods[i],ratings[i]);
            ranked.computeIfAbsent(cuisines[i],key->new TreeSet<>(order)).add(foods[i]);
        }
    }
    public void changeRating(String food,int newRating){
        TreeSet<String> set=ranked.get(cuisines.get(food));
        set.remove(food);
        ratings.put(food,newRating);
        set.add(food);
    }
    public String highestRated(String cuisine){
        return ranked.get(cuisine).first();
    }
}

